import { setTimeout as wait } from 'node:timers/promises';
const INITIAL_BACKOFF_MS = 200;
const MAX_RETRY_DURATION_MS = 30_000;
/** The retry budget starts after the first 429; caller aborts and other errors propagate. */ export function withRateLimitRetries({ fetchImplementation, warn }) {
    return async (input, init)=>{
        const request = input instanceof Request && init == null ? input.clone() : new Request(input, init);
        request.signal.throwIfAborted();
        let response = await fetchImplementation(request.clone());
        if (response.status !== 429) {
            return response;
        }
        const timeoutReason = new DOMException('Rate-limit retry budget exhausted', 'TimeoutError');
        const retryController = new AbortController();
        const signal = AbortSignal.any([
            request.signal,
            retryController.signal
        ]);
        const timeout = globalThis.setTimeout(()=>retryController.abort(timeoutReason), MAX_RETRY_DURATION_MS);
        let attempt = 0;
        try {
            while(response.status === 429){
                signal.throwIfAborted();
                const backoffMs = INITIAL_BACKOFF_MS * 2 ** attempt;
                const delayMs = backoffMs + Math.random() * backoffMs;
                warn(`HTTP 429 from ${request.url}; retrying in ${Math.round(delayMs)}ms`);
                await wait(delayMs, undefined, {
                    signal
                });
                signal.throwIfAborted();
                // Only the caller can abort an in-flight request: a retry may have already written data.
                response = await fetchImplementation(request.clone());
                attempt += 1;
            }
            return response;
        } catch (error) {
            const isRetryTimeout = error === timeoutReason || error instanceof Error && error.name === 'AbortError' && error.cause === timeoutReason;
            if (isRetryTimeout && !request.signal.aborted) {
                return response;
            }
            throw error;
        } finally{
            globalThis.clearTimeout(timeout);
        }
    };
}
